"""
views/vm_list_view.py — sidebar VM list with right-click context menu.

GTK4 right-click implementation:
  - GestureClick(button=0) at CAPTURE phase on the ListBox intercepts ALL
    pointer events before any child widget sees them. We filter for button=3
    inside the handler. CAPTURE phase is essential — Adw.ActionRow claims
    button-1 events at CAPTURE phase itself, and a BUBBLE-phase button-3
    gesture never fires because ActionRow stops the sequence first.
  - insert_action_group() is called before set_parent() so GTK can resolve
    action targets when the popover enters the widget tree.
  - The popover is parented to the ListBox for correct coordinate space.
  - get_row_at_y() maps the CAPTURE-phase y coordinate to the correct row.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, Gdk, Gio, GLib
from typing import Callable

from ..backend.libvirt_manager import (
    DomainInfo, LibvirtManager, DEFAULT_TRUST_LEVELS
)
from .vm_create_dialog import VMCreateDialog


def _trust_color(trust: str, defs: dict) -> str:
    return defs.get(trust, defs.get("unknown", {})).get("color", "#888888")


_STATE_CSS = {
    "Running":       "success",
    "Stopped":       "",
    "Paused":        "warning",
    "Shutting down": "warning",
    "Crashed":       "error",
    "Suspended":     "warning",
}


class VMListView(Adw.NavigationPage):
    def __init__(
        self,
        on_select: Callable[[DomainInfo], None],
        manager: LibvirtManager,
        on_open_config: Callable[[DomainInfo], None] | None = None,
        on_open_xml: Callable[[DomainInfo], None] | None = None,
    ):
        super().__init__(title="BulwarkOS", tag="vm-list")
        self._on_select      = on_select
        self._manager        = manager
        self._on_open_config = on_open_config
        self._on_open_xml    = on_open_xml
        self._rows: dict[str, tuple[Adw.ActionRow, Gtk.Label, Gtk.DrawingArea]] = {}
        self._domains: list[DomainInfo] = []
        self.selected_name: str | None  = None
        self._active_popover: Gtk.PopoverMenu | None = None

        # ── Header ────────────────────────────────────────────────────────
        self._header = Adw.HeaderBar()
        self._header.set_show_end_title_buttons(False)

        btn_new = Gtk.Button()
        btn_new.set_icon_name("list-add-symbolic")
        btn_new.set_tooltip_text("New virtual machine")
        btn_new.connect("clicked", self._on_new_vm)
        self._header.pack_end(btn_new)

        # ── Search ────────────────────────────────────────────────────────
        self._search_entry = Gtk.SearchEntry()
        self._search_entry.set_placeholder_text("Search VMs…")
        self._search_entry.connect(
            "search-changed", lambda _: self._list_box.invalidate_filter()
        )

        # ── List ──────────────────────────────────────────────────────────
        self._list_box = Gtk.ListBox()
        self._list_box.set_selection_mode(Gtk.SelectionMode.SINGLE)
        self._list_box.add_css_class("navigation-sidebar")
        self._list_box.set_filter_func(self._filter_func)
        self._list_box.connect("row-selected", self._on_row_selected)

        # ── Pointer gesture — CAPTURE phase, all buttons ──────────────────
        # button=0 means "watch all buttons". We filter for button 3 (right-
        # click) inside the handler. CAPTURE phase is mandatory: it fires
        # before child widgets see the event, so Adw.ActionRow cannot claim
        # and swallow the sequence first.
        self._gesture = Gtk.GestureClick.new()
        self._gesture.set_button(0)  # all buttons
        self._gesture.set_propagation_phase(Gtk.PropagationPhase.CAPTURE)
        self._gesture.connect("pressed", self._on_gesture_pressed)
        self._list_box.add_controller(self._gesture)

        # Long-press for touch
        self._long_press = Gtk.GestureLongPress.new()
        self._long_press.set_propagation_phase(Gtk.PropagationPhase.CAPTURE)
        self._long_press.connect("pressed", self._on_long_press)
        self._list_box.add_controller(self._long_press)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(self._list_box)

        self._spinner = Gtk.Spinner()
        self._spinner.set_size_request(32, 32)
        self._spinner.set_halign(Gtk.Align.CENTER)
        self._spinner.set_valign(Gtk.Align.CENTER)
        self._spinner.start()

        self._stack = Gtk.Stack()
        self._stack.add_named(self._spinner, "loading")
        self._stack.add_named(scroll, "list")
        self._stack.set_visible_child_name("loading")

        self._empty_label = Gtk.Label(label="No virtual machines found.")
        self._empty_label.add_css_class("dim-label")
        self._empty_label.set_margin_top(32)
        self._stack.add_named(self._empty_label, "empty")

        toolbar = Adw.ToolbarView()
        toolbar.add_top_bar(self._header)
        toolbar.add_top_bar(self._search_entry)
        toolbar.set_content(self._stack)
        self.set_child(toolbar)

    # ------------------------------------------------------------------ #
    # Public                                                               #
    # ------------------------------------------------------------------ #

    def update(self, domains: list[DomainInfo]):
        self._domains = domains
        self._spinner.stop()

        seen: set[str] = set()
        for info in domains:
            seen.add(info.name)
            if info.name in self._rows:
                self._update_row(info)
            else:
                self._add_row(info)

        for name in list(self._rows.keys()):
            if name not in seen:
                row, _lbl, _dot = self._rows.pop(name)
                self._list_box.remove(row)

        self._list_box.invalidate_filter()
        self._stack.set_visible_child_name("list" if domains else "empty")

    # ------------------------------------------------------------------ #
    # Row construction                                                     #
    # ------------------------------------------------------------------ #

    def _add_row(self, info: DomainInfo):
        row = Adw.ActionRow()
        row.set_activatable(True)

        trust_dot = Gtk.DrawingArea()
        trust_dot.set_size_request(10, 10)
        trust_dot.set_valign(Gtk.Align.CENTER)
        defs_snap = self._manager.get_trust_defs()
        hex_color = _trust_color(info.meta.get("trust", "unknown"), defs_snap)

        def _draw(da, cr, w, h, hx=hex_color):
            rgba = Gdk.RGBA()
            rgba.parse(hx)
            cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 1.0)
            cr.arc(w / 2, h / 2, w / 2, 0, 2 * 3.14159)
            cr.fill()

        trust_dot.set_draw_func(_draw)
        row.add_prefix(trust_dot)

        icon = Gtk.Image.new_from_icon_name(
            info.meta.get("icon", "computer-symbolic")
        )
        icon.set_pixel_size(16)
        row.add_prefix(icon)

        label = info.meta.get("label", info.name)
        row.set_title(label)
        if label != info.name:
            row.set_subtitle(info.name)

        state_lbl = Gtk.Label(label=info.state_name)
        state_lbl.set_valign(Gtk.Align.CENTER)
        state_css = _STATE_CSS.get(info.state_name, "")
        if state_css:
            state_lbl.add_css_class(state_css)
        state_lbl.add_css_class("caption")
        row.add_suffix(state_lbl)

        row.set_name(info.name)
        self._rows[info.name] = (row, state_lbl, trust_dot)
        self._list_box.append(row)

    def _update_row(self, info: DomainInfo):
        row, state_lbl, trust_dot = self._rows[info.name]

        display_label = info.meta.get("label", info.name)
        row.set_title(display_label)
        row.set_subtitle(info.name if display_label != info.name else "")

        state_lbl.set_label(info.state_name)
        for cls in ("success", "warning", "error", "accent"):
            state_lbl.remove_css_class(cls)
        state_css = _STATE_CSS.get(info.state_name, "")
        if state_css:
            state_lbl.add_css_class(state_css)

        defs_snap = self._manager.get_trust_defs()
        new_color  = _trust_color(info.meta.get("trust", "unknown"), defs_snap)

        def _draw_updated(da, cr, w, h, hx=new_color):
            rgba = Gdk.RGBA()
            rgba.parse(hx)
            cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 1.0)
            cr.arc(w / 2, h / 2, w / 2, 0, 2 * 3.14159)
            cr.fill()

        trust_dot.set_draw_func(_draw_updated)
        trust_dot.queue_draw()

    # ------------------------------------------------------------------ #
    # Gesture handlers                                                     #
    # ------------------------------------------------------------------ #

    def _row_and_info_at(self, y: float):
        """Return (Gtk.ListBoxRow, DomainInfo) for the row at y, or (None, None)."""
        list_row = self._list_box.get_row_at_y(int(y))
        if list_row is None:
            return None, None
        name = list_row.get_name()
        for info in self._domains:
            if info.name == name:
                return list_row, info
        return None, None

    def _on_gesture_pressed(
        self,
        gesture: Gtk.GestureClick,
        n_press: int,
        x: float,
        y: float,
    ):
        # Only handle right-click (button 3) — let all other buttons pass through
        if gesture.get_current_button() != 3:
            gesture.set_state(Gtk.EventSequenceState.DENIED)
            return

        list_row, info = self._row_and_info_at(y)
        if info is None:
            gesture.set_state(Gtk.EventSequenceState.DENIED)
            return

        # Claim the sequence immediately so the row doesn't activate
        gesture.set_state(Gtk.EventSequenceState.CLAIMED)

        # Select the row so the detail pane stays in sync
        self._list_box.select_row(list_row)

        self._show_context_menu(info, x, y)

    def _on_long_press(
        self,
        gesture: Gtk.GestureLongPress,
        x: float,
        y: float,
    ):
        list_row, info = self._row_and_info_at(y)
        if info is None:
            return
        self._list_box.select_row(list_row)
        self._show_context_menu(info, x, y)

    # ------------------------------------------------------------------ #
    # Context menu                                                         #
    # ------------------------------------------------------------------ #

    def _show_context_menu(self, info: DomainInfo, x: float, y: float):
        # Dismiss any existing popover first
        if self._active_popover is not None:
            self._active_popover.popdown()
            self._active_popover = None

        running = info.is_running
        stopped = info.is_stopped
        paused  = info.is_paused
        name    = info.name
        lbl     = info.meta.get("label", name)

        # ── Menu model ────────────────────────────────────────────────────
        menu = Gio.Menu()

        power_sec = Gio.Menu()
        power_sec.append("Start",      "ctx.start")
        power_sec.append("Shutdown",   "ctx.shutdown")
        power_sec.append("Restart",    "ctx.restart")
        power_sec.append("Hard Reset", "ctx.reset")
        power_sec.append("Force Stop", "ctx.force_stop")
        power_sec.append("Pause",      "ctx.pause")
        power_sec.append("Resume",     "ctx.resume")
        menu.append_section(None, power_sec)

        console_sec = Gio.Menu()
        console_sec.append("Open Console", "ctx.console")
        menu.append_section(None, console_sec)

        config_sec = Gio.Menu()
        config_sec.append("Configure…", "ctx.configure")
        config_sec.append("Edit XML…",  "ctx.edit_xml")
        menu.append_section(None, config_sec)

        delete_sec = Gio.Menu()
        delete_sec.append("Delete VM…", "ctx.delete")
        menu.append_section(None, delete_sec)

        # ── Action group ──────────────────────────────────────────────────
        ag = Gio.SimpleActionGroup()

        def _add(action_name: str, enabled: bool, cb):
            a = Gio.SimpleAction.new(action_name, None)
            a.set_enabled(enabled)
            a.connect("activate", lambda *_: cb())
            ag.add_action(a)

        _add("start",      stopped,
             lambda: self._act(self._manager.start_domain, name))
        _add("shutdown",   running,
             lambda: self._confirm_act(
                 f"Shut down {lbl}?",
                 "The VM will receive an ACPI shutdown signal. Unsaved work may be lost.",
                 lambda: self._act(self._manager.shutdown_domain, name),
             ))
        _add("restart",    running,
             lambda: self._act(self._manager.restart_domain, name))
        _add("reset",      running,
             lambda: self._confirm_act(
                 f"Hard reset {lbl}?",
                 "Equivalent to pressing the physical reset button.",
                 lambda: self._act(self._manager.reset_domain, name),
             ))
        _add("force_stop", running or paused,
             lambda: self._confirm_act(
                 f"Force stop {lbl}?",
                 "Equivalent to cutting power. Data loss may occur.",
                 lambda: self._act(self._manager.force_stop_domain, name),
                 destructive=True,
             ))
        _add("pause",      running,
             lambda: self._act(self._manager.pause_domain, name))
        _add("resume",     paused,
             lambda: self._act(self._manager.resume_domain, name))
        _add("console",    running,
             lambda: self._act(self._manager.open_console, name))
        _add("configure",  True, lambda: self._open_config(info))
        _add("edit_xml",   True, lambda: self._open_xml(info))
        _add("delete",     True,
             lambda: self._confirm_act(
                 f"Delete {lbl}?",
                 "This will undefine the VM. The disk image will not be deleted.",
                 lambda: self._act(self._manager.delete_domain, name, False),
                 destructive=True,
             ))

        # ── Popover — action group inserted BEFORE set_parent ─────────────
        # GTK resolves action targets when the widget enters the tree.
        # Registering the group after set_parent causes all items to appear
        # insensitive because the menu model was already frozen.
        popover = Gtk.PopoverMenu.new_from_model(menu)
        popover.insert_action_group("ctx", ag)   # ← must be before set_parent
        popover.set_parent(self._list_box)        # ← enter the tree after
        popover.set_has_arrow(False)

        rect = Gdk.Rectangle()
        rect.x      = int(x)
        rect.y      = int(y)
        rect.width  = 1
        rect.height = 1
        popover.set_pointing_to(rect)

        def _on_closed(_pop):
            _pop.unparent()
            if self._active_popover is _pop:
                self._active_popover = None

        popover.connect("closed", _on_closed)
        self._active_popover = popover
        popover.popup()

    # ------------------------------------------------------------------ #
    # Action helpers                                                       #
    # ------------------------------------------------------------------ #

    def _act(self, fn, *args):
        fn(*args)

    def _confirm_act(self, heading, body, on_confirm, destructive=False):
        dialog = Adw.MessageDialog(
            transient_for=self.get_root(),
            heading=heading,
            body=body,
        )
        dialog.add_response("cancel",  "Cancel")
        dialog.add_response("confirm", "Confirm")
        if destructive:
            dialog.set_response_appearance(
                "confirm", Adw.ResponseAppearance.DESTRUCTIVE
            )
        dialog.connect(
            "response",
            lambda d, r: on_confirm() if r == "confirm" else None,
        )
        dialog.present()

    def _open_config(self, info: DomainInfo):
        if self._on_open_config:
            self._on_open_config(info)
        else:
            from .vm_config_dialog import VMConfigDialog
            VMConfigDialog(manager=self._manager, info=info).present(self)

    def _open_xml(self, info: DomainInfo):
        if self._on_open_xml:
            self._on_open_xml(info)
        else:
            from .vm_xml_dialog import VMXmlDialog
            VMXmlDialog(manager=self._manager, info=info).present(self)

    # ------------------------------------------------------------------ #
    # Selection                                                            #
    # ------------------------------------------------------------------ #

    def _on_row_selected(self, _, row):
        if row is None:
            return
        name = row.get_name()
        self.selected_name = name
        for info in self._domains:
            if info.name == name:
                self._on_select(info)
                return

    # ------------------------------------------------------------------ #
    # Filter                                                               #
    # ------------------------------------------------------------------ #

    def _filter_func(self, row) -> bool:
        query = self._search_entry.get_text().lower().strip()
        if not query:
            return True
        name = row.get_name().lower()
        for info in self._domains:
            if info.name == row.get_name():
                label = info.meta.get("label", "").lower()
                return query in name or query in label
        return query in name

    # ------------------------------------------------------------------ #
    # New VM                                                               #
    # ------------------------------------------------------------------ #

    def _on_new_vm(self, _btn):
        dialog = VMCreateDialog(
            manager=self._manager,
            on_created=self._on_vm_created,
            parent=self,
        )
        dialog.present(self)

    def _on_vm_created(self, name: str):
        self.selected_name = name
